<script setup>
import { computed, onUnmounted, ref, watch } from 'vue'
const categories = ['全部', '清淡', '重口', '素食']
const defaults = [['番茄炒蛋','🍅','清淡'],['麻辣香锅','🌶️','重口'],['日式拉面','🍜','清淡'],['快乐汉堡','🍔','重口'],['鲜蔬沙拉','🥗','素食'],['热气火锅','🍲','重口'],['香菇青菜','🥬','素食'],['暖胃馄饨','🥟','清淡']].map(([name,emoji,category],i)=>({id:String(i+1),name,emoji,category}))
const colors = ['#f9d7a1','#f1a580','#e8edcf','#f5c4a9','#e4e9d0','#f5c39a','#d6e0bd','#f8e4ba','#efb69e','#e7d8b6','#e4e8ce','#f5d2b0']
const notice = ref('')
function load(){try{const v=JSON.parse(localStorage.getItem('fandian-v1')||'null');if(!v||!Array.isArray(v.meals))return null;return{meals:v.meals.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&x.name.trim()&&x.name.length<=8&&typeof x.emoji==='string'&&categories.slice(1).includes(x.category)).slice(0,12),history:Array.isArray(v.history)?v.history.filter(x=>x&&typeof x.name==='string'&&typeof x.emoji==='string'&&typeof x.time==='string').slice(0,5):[]}}catch{notice.value='无法读取本地记录，你仍然可以正常使用。';return null}}
const saved=load(), meals=ref(saved?.meals??defaults), history=ref(saved?.history??[]), category=ref('全部'), excluded=ref([]), rotation=ref(0), spinning=ref(false), result=ref(null), newName=ref(''), newCategory=ref('清淡'), showForm=ref(false)
const candidates=computed(()=>meals.value.filter(x=>(category.value==='全部'||x.category===category.value)&&!excluded.value.includes(x.id)))
const wheelBackground=computed(()=>candidates.value.length?`conic-gradient(${candidates.value.map((_,i)=>`${colors[i]} ${i*360/candidates.value.length}deg ${(i+1)*360/candidates.value.length}deg`).join(',')})`:'#eee9de')
let timer
watch([meals,history],()=>{try{localStorage.setItem('fandian-v1',JSON.stringify({meals:meals.value,history:history.value}))}catch{notice.value='浏览器未能保存数据，关闭页面后修改可能丢失。'}},{deep:true})
watch(category,()=>result.value=null);onUnmounted(()=>clearTimeout(timer))
function labelStyle(i){const a=(i+.5)*360/candidates.value.length*Math.PI/180;return{left:`${50+Math.sin(a)*33}%`,top:`${50-Math.cos(a)*33}%`}}
function spin(){if(spinning.value||!candidates.value.length)return;const i=Math.floor(Math.random()*candidates.value.length),picked={...candidates.value[i]},target=360-(i+.5)*360/candidates.value.length,current=(rotation.value%360+360)%360;rotation.value+=1800+(target-current+360)%360;result.value=null;spinning.value=true;timer=setTimeout(()=>{result.value=picked;spinning.value=false;history.value=[{name:picked.name,emoji:picked.emoji,time:new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})},...history.value].slice(0,5)},matchMedia('(prefers-reduced-motion: reduce)').matches?80:4200)}
function skip(){if(result.value&&!spinning.value){excluded.value.push(result.value.id);result.value=null}}
function addMeal(){const name=newName.value.trim();if(!name||spinning.value)return;if(meals.value.length>=12){notice.value='最多放入 12 道菜，先移除一道再添加吧。';return}if(meals.value.some(x=>x.name===name)){notice.value='这道菜已经在菜单里啦。';return}meals.value.push({id:crypto.randomUUID(),name,category:newCategory.value,emoji:{清淡:'🍚',重口:'🌶️',素食:'🥦'}[newCategory.value]});newName.value='';notice.value='';showForm.value=false}
function removeMeal(id){if(!spinning.value){meals.value=meals.value.filter(x=>x.id!==id);if(result.value?.id===id)result.value=null}}
</script>
<template><div class="shell"><header class="topbar"><a class="brand" href="./"><span>◒</span>饭点 <small>FAN DIAN</small></a><div>● 好好吃饭，是件正经事</div></header><main><section class="intro"><small>— &nbsp; A LITTLE HELP FOR YOUR EVERYDAY</small><h1>今天吃什么<span>?</span></h1><p>选择困难就交给运气，把时间留给好好吃饭。</p><b class="doodle">✳</b></section><div class="layout"><section class="wheel-panel"><div class="panel-top">你的美味，随机派送 <small>LET IT SPIN ↗</small></div><nav class="filters"><button v-for="item in categories" :key="item" :class="{active:category===item}" :disabled="spinning" @click="category=item">{{item==='全部'?'🍽️ 全部口味':item}}</button></nav><div class="wheel-stage"><div class="wheel-frame"><div class="pointer"></div><div class="wheel" :style="{background:wheelBackground,transform:`rotate(${rotation}deg)`}"><div v-for="(meal,i) in candidates" :key="meal.id" class="wheel-label" :style="labelStyle(i)"><span>{{meal.emoji}}</span><b>{{meal.name}}</b></div></div><div class="wheel-center">🍴<small>GOOD FOOD<br>GOOD MOOD</small></div></div></div><button class="spin-button" :disabled="spinning||!candidates.length" @click="spin">{{spinning?'美味正在赶来…':candidates.length?(result?'再转一次':'转一下，开饭！'):'还没有可选的菜'}} <b>↗</b></button><p class="hint">{{candidates.length?`${candidates.length} 道美味候选 · 每一道都有同等机会`:'试试其他口味，或添加你想吃的菜'}}</p><p v-if="excluded.length" class="excluded">已跳过 {{excluded.length}} 道菜 <button @click="excluded=[];result=null">全部放回</button></p></section><aside class="side"><section class="result-card" aria-live="polite"><div class="caption">● {{spinning?'命运的齿轮转动中':result?'今天的美味答案':'给生活一点小惊喜'}}</div><div class="result-emoji">{{spinning?'💫':result?.emoji||'🍳'}}</div><h2>{{spinning?'好吃的值得等待':result?.name||'下一顿，值得期待'}}</h2><p>{{spinning?'稍等一下，答案马上揭晓…':result?'就是它了！今天也要吃得开心。':'点击转盘，看看今天与哪道美味有缘。'}}</p><button v-if="result&&!spinning" class="skip" @click="skip">今天不想吃这个 ↗</button></section><section class="menu-card"><div class="section-heading"><h2>我的菜单 <small>{{meals.length}}/12</small></h2><button class="add-button" :disabled="spinning||meals.length>=12" @click="showForm=!showForm">{{showForm?'收起':'＋ 添加'}}</button></div><form v-if="showForm" class="add-form" @submit.prevent="addMeal"><label for="meal-name">想吃的菜</label><input id="meal-name" v-model="newName" placeholder="例如：宫保鸡丁" maxlength="8" required><div><select v-model="newCategory"><option v-for="item in categories.slice(1)" :key="item">{{item}}</option></select><button :disabled="!newName.trim()">加入菜单</button></div></form><div class="meal-list"><div v-for="meal in meals" :key="meal.id" class="meal-row" :class="{muted:excluded.includes(meal.id)}"><span>{{meal.emoji}}</span><b>{{meal.name}}</b><small>{{meal.category}}</small><button :aria-label="`移除${meal.name}`" :disabled="spinning" @click="removeMeal(meal.id)">×</button></div><p v-if="!meals.length" class="empty">菜单空了，添加第一道美味吧。</p></div><p class="local-note">⌁ 菜单保存在当前浏览器，不会上传</p></section></aside></div><p v-if="notice" class="notice" role="status">{{notice}} <button @click="notice=''">×</button></p><section class="history"><div class="section-heading"><h2>最近的美味缘分 <small>RECENT PICKS</small></h2><small>只记录最近 5 次</small></div><div v-if="history.length" class="history-list"><div v-for="(item,i) in history" :key="`${item.time}-${i}`" class="history-item"><span>{{item.emoji}}</span><div><b>{{item.name}}</b><small>{{item.time}}</small></div></div></div><p v-else class="empty-history">还没有抽签记录。第一份美味，等你转出来。</p></section></main><footer><span>少一点纠结，多一点美味。</span><small>MADE FOR YOUR EVERYDAY　✳</small></footer></div></template>
